INSERT INTO `command_configs` VALUES (14,'Suspender Servicio','suspends_services_early_in_the_day:process','1','00:01','Suspende los servicios recurrentes que no esten pagados',1,NULL,'2024-02-09 17:45:30'),(15,'Servicio de facturación','billing_service_command:process','1','00:02','Cobra los servicios que No están pagados, tienen dinero en la cuenta y el dia de facturación es hoy o ya pasó, los activa y crea una factura',1,NULL,'2024-02-09 17:45:30'),(16,'Crear Factura a Clientes Personalizados','addinvoicedefaultertoclients:process','1','00:05','Crea facturas a Clientes Personalizados cuando no paguen a tiempo y excedan un mes y 1 día',1,NULL,'2024-02-09 17:45:30'),(17,'Eliminar Clientes del Mikrotik que no tengan Servicios','removeinmikrotikwithoutclientservice:process','2','','Elimina todos los clientes del Mikrotik que no tengan servicios en el sistema',1,NULL,'2024-02-09 17:45:30'),(18,'Agregar a mikrotik servicios que no han sido montados','deployclientsinaddresslist:process','2','','Recorre la tabla service_in_address_list y monta en el mikrotik los servicios que no han sido montados',1,NULL,'2024-02-09 17:45:30'),(19,'Pasar clientes bloqueados a inactivos','maketheclientinactive:process','2','','Todos los clientes que esten bloqueados, que hayan sido desplegados y que hayan cobrado su primera vez que sean igual o sebrepasenn su tiempo de gracia pasaran a inactivos',1,NULL,'2024-02-09 17:45:30'),(20,'Eliminar o Actualizar Clientes en Mikrotik','actionpoolinmikrotik:process','2','','Elimina o actualiza Pools en los mikrotik dada las ubicaciones',1,NULL,'2024-02-09 17:45:30'),(21,'Crear Pool en Mikrotik','createpoolinmikrotik:process','2','','Despliega los pools creados en bases de datos en el Mikrotik dada la ubicación',1,NULL,'2024-02-09 17:45:30'),(22,'Crear copia de seguridad de Mikrotik','mikrotikBackup:process','1','23:59','Hace una copia de seguridad de Mikrotik diariamente',1,NULL,'2024-02-09 17:45:30'),(23,'Agregar facturas a Clientes con Periodo de Gracia Activo','add_invoice_and_rectify_balance_for_clients_with_grace_period:process','1','00:03','Agrega factura y Rectifica el balance a clientes con periodo de gracia activo',1,NULL,NULL),(24,'Agregar Factura','create_client_invoice_command:process','1','00:04','Crea facturas para los diferentes tipos de clientes recurrentes y custom',1,NULL,NULL);
